static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
static void Reject(Action action,string code){try{action();}catch(IntegrationException e){Check(e.Code==code,"Unexpected error "+e.Code);return;}throw new Exception("Expected "+code);}
var folder=Path.Combine(Path.GetTempPath(),"marketpilot-catalog-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
try{
    var env=new TestEnvironment{ContentRootPath=folder};var db=new DemoStore(env);var registry=new IntegrationRegistry(env);var demo=new DemoWorkspace(env);var hub=new CatalogHub(db,registry,demo);hub.Ensure();
    Check(hub.Search(new()).TotalElements==17,"Legacy products must remain alongside eight mapped demo variants");var row=hub.Search(new(Search:"8691000000001")).Items.Single();Check(row.ListingCount==7,"Each store must have an independent link");var original=row.Product;
    var store=registry.Connections["trendyol"];var first=new CatalogCandidate(CatalogHub.Key(store.Id,"new-valid"),"new-valid","NEW-ROLLBACK","8698888888888","Rollback candidate","Test","",1,10,"TRY",true,"approved");var conflicting=first with{Key=CatalogHub.Key(store.Id,"new-conflict"),ExternalId="new-conflict",Sku=original.Sku,Barcode="8697777777777"};var batch=new CandidateBatch("test",store.Id,CatalogHub.Source(store),DateTimeOffset.UtcNow,[first,conflicting],0,null,false);
    Reject(()=>hub.Import(batch,[first.Key,conflicting.Key]),"identity_conflict");Check(hub.Search(new(Search:"NEW-ROLLBACK")).TotalElements==0,"Partial import leaked into memory");Check(new DemoStore(env).SearchProducts(new(Search:"NEW-ROLLBACK")).TotalElements==0,"Partial import leaked to disk");
    var real=new ConnectionState("real-test",new("Live test","trendyol","real","production"),"untested",null,null,null,null,null);registry.Connections[real.Id]=real;var native=first with{Key=CatalogHub.Key(real.Id,"real-1"),ExternalId="real-1",Sku=original.Sku,Barcode=original.Barcode,Stock=1.5m,Price=null,Currency="",VatIncluded=false};hub.Import(new("real",real.Id,CatalogHub.Source(real),DateTimeOffset.UtcNow,[native],0,null,false),[native.Key]);var separated=hub.Search(new(Search:original.Barcode));Check(separated.Items.Count==2,"Demo and real master must remain separate");var realProduct=separated.Items.Single(r=>r.Product.SourceMode=="real").Product;Check(realProduct.Stock==1.5m&&!realProduct.PriceKnown&&realProduct.Currency==""&&realProduct.VatIncluded==false,"Unknown currency/price and decimal quantities were lost");Reject(()=>hub.Remap(new(native.Key,original.Id)),"mode_mismatch");Check(!hub.Preview([native.Key]).Single().Ready,"Real writes must be blocked");
    CatalogEdit Change(Product p,decimal stock)=>new(p.Name,p.Sku,p.Barcode,p.Category,p.Brand,p.Description,stock,p.Price,p.Currency,p.VatIncluded,p.Status,p.Version);
    var demoLink=row.Listings.Single(l=>l.StoreId=="trendyol");var request=new CatalogPublish("stale-job",[demoLink.Key],new(){{original.Id,original.Version}});hub.Publish(request);hub.Edit(original.Id,Change(original,41));await hub.Tick(default);var stale=db.CatalogRead(s=>s.Catalog.Jobs.Single(j=>j.RequestId=="stale-job"));Check(stale.State=="failed","Queued stale product must fail before dispatch");
    var latest=hub.Search(new(Search:original.Barcode,Mode:"demo")).Items.Single().Product;hub.Publish(new("resume-job",[demoLink.Key],new(){{latest.Id,latest.Version}}));
    var restartedDb=new DemoStore(env);var restartedDemo=new DemoWorkspace(env);var restarted=new CatalogHub(restartedDb,registry,restartedDemo);restarted.Ensure();await restarted.Tick(default);await Task.Delay(2200);restartedDemo.ProcessPendingJobs();await restarted.Tick(default);Check(restartedDb.CatalogRead(s=>s.Catalog.Jobs.Single(j=>j.RequestId=="resume-job").State)=="completed","Restart did not resume pending dispatch");Check(restartedDemo.Snapshot(store.Settings).Products.First(p=>p.Barcode==original.Barcode).Stock==41,"Dispatched stock missing");
    var operations=new OperationsHub(restartedDb,registry,restartedDemo);var nativeOrder=restartedDemo.Snapshot(store.Settings).Orders[0] with{PackageId="real-package",OrderNumber="REAL-TEST-1",Cargo=new("Test carrier","REAL-TRACK","","","",null,null)};operations.Observe(real,new MarketplacePage<MarketplaceOrder>([nativeOrder],0,25,1,1,null));operations.Observe(real,new MarketplacePage<MarketplaceOrder>([nativeOrder with{Status="Shipped"}],0,25,1,1,null));var captured=operations.Orders(new(Search:"REAL-TEST-1"));Check(captured.Items.Count==1&&captured.Items[0].Status=="Kargolandı"&&captured.Items[0].Lines[0].ProductId==realProduct.Id,"Observed real order page did not upsert/link to real master");Check(operations.Shipments(new(Search:"REAL-TRACK")).Items.Count==1,"Observed tracking missing");Check(new DemoStore(env).CatalogRead(s=>s.Catalog.Orders.Count)==1,"Read-page order snapshot did not persist");
    var sw=Stopwatch.StartNew();restartedDb.Modify(s=>{for(var i=0;i<100000;i++)s.Products.Add(new Product{Id="scale-"+i,Name="Scale row "+i,Sku="SCALE-"+i,Stock=i,Price=10,SourceMode="real"});return true;});var page=restarted.Search(new(Search:"Scale row",Page:3999));Check(page.Items.Count==25&&page.TotalElements==100000&&page.TotalPages==4000,"Filtering/paging broke with 100k products");Check(JsonSerializer.Serialize(page).Length<100000,"Returned full catalogue instead of one page");var elapsed=sw.ElapsedMilliseconds;
    var backups=new LocalBackups(env);var backup=backups.Create();backups.Verify(backup.Name);Check(new DemoStore(env).CatalogRead(s=>s.Catalog.Listings.ContainsKey(native.Key)),"Shared catalogue metadata did not persist");
    Console.WriteLine($"PASS shared catalogue domain: legacy preservation, exact store links, atomic import rollback, demo/live separation, decimal/unknown values, live-write guard, stale queued versions, restart recovery, 100k products with 25-row response ({elapsed} ms including fixture persistence), encrypted backup coverage.");
